SELECT 	hodnotitel."Kód" "Kód hodnotitele",
	hodnotitel."Externí hodnotitel" ,
	hodnotitel."Pøíjmení",
	hodnotitel."Kód",
	hodnotitel."Název",
	hodnotitel."Jméno",
	hodnotitel.id
FROM isum.v_bi_UmvHodnotitel hodnotitel 

WHERE 	hodnotitel."Externí hodnotitel" = 'A'

--------------------------------------------------


